// Enhancement: "Describe a bot" → full bot definition, generated by the local LLM.
import { chatJSON } from './llm.js';
import { BUILTIN_SLOT_TYPES } from './slotTypes.js';
import { makeBot } from './templates.js';

const BUILTINS = Object.keys(BUILTIN_SLOT_TYPES);

const SCHEMA = {
  type: 'object',
  properties: {
    name: { type: 'string' },
    description: { type: 'string' },
    welcome: { type: 'string' },
    slotTypes: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          name: { type: 'string' },
          values: { type: 'array', items: { type: 'object', properties: { value: { type: 'string' }, synonyms: { type: 'array', items: { type: 'string' } } }, required: ['value', 'synonyms'] } },
        },
        required: ['name', 'values'],
      },
    },
    intents: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          name: { type: 'string' },
          description: { type: 'string' },
          utterances: { type: 'array', items: { type: 'string' } },
          slots: {
            type: 'array',
            items: {
              type: 'object',
              properties: { name: { type: 'string' }, type: { type: 'string' }, prompt: { type: 'string' } },
              required: ['name', 'type', 'prompt'],
            },
          },
          confirmationPrompt: { type: 'string' },
          closingResponse: { type: 'string' },
        },
        required: ['name', 'description', 'utterances', 'slots', 'confirmationPrompt', 'closingResponse'],
      },
    },
  },
  required: ['name', 'description', 'slotTypes', 'intents'],
};

const SYSTEM = `You design Amazon Lex V2 chatbots. Given a short description, output a bot definition as JSON.
Rules:
- name: PascalCase, no spaces, ends with "Bot".
- 2 to 4 intents, PascalCase names (e.g. BookAppointment). 5-8 varied sample utterances each.
- Utterances may reference slots with curly braces, e.g. "book a {RoomType} room for {Nights} nights". Only reference slots of that intent.
- Slot names PascalCase. Slot type must be one of the built-ins ${BUILTINS.join(', ')} OR the name of a custom slot type you define in slotTypes.
- Custom slot types: PascalCase names ending in "Type", 3-8 values each with 0-3 synonyms.
- Slot prompts are short questions. confirmationPrompt and closingResponse may reference slots with {SlotName}. Use "" for confirmationPrompt on informational intents.
- Keep it realistic and concise.`;

// Map whatever type name the model produced onto a real slot type.
function pickType(slot, typeNames) {
  const t = (slot.type || '').replace(/\s/g, '');
  if (BUILTINS.includes(t) || typeNames.has(t)) return t;
  const lc = (x) => x.toLowerCase().replace(/type$/, '');
  const custom = [...typeNames].find((n) => lc(n) === lc(t) || lc(n) === lc(slot.name));
  if (custom) return custom;
  const builtin = BUILTINS.find((b) => lc(b.split('.')[1]) === lc(t.split('.').pop()));
  if (builtin) return builtin;
  const n = `${slot.name} ${t}`.toLowerCase();
  if (/quantity|count|number|nights|people|guests|age/.test(n)) return 'AMAZON.Number';
  if (/date|day/.test(n)) return 'AMAZON.Date';
  if (/time/.test(n)) return 'AMAZON.Time';
  if (/city|destination|origin/.test(n)) return 'AMAZON.City';
  if (/phone/.test(n)) return 'AMAZON.PhoneNumber';
  if (/email/.test(n)) return 'AMAZON.EmailAddress';
  if (/name/.test(n)) return 'AMAZON.FirstName';
  if (/id$|ref|code/.test(n)) return 'AMAZON.AlphaNumeric';
  return 'AMAZON.FreeFormInput';
}

export async function generateBot(settings, description) {
  const { data, ms } = await chatJSON(settings, { system: SYSTEM, user: description, schema: SCHEMA, temperature: 0.4 });
  const typeNames = new Set((data.slotTypes || []).map((t) => t.name));
  const bot = makeBot({
    name: (data.name || 'GeneratedBot').replace(/\W/g, ''),
    description: data.description || description,
    slotTypes: (data.slotTypes || []).filter((t) => t.values?.length).map((t) => ({
      name: t.name.replace(/\W/g, ''),
      description: '',
      resolution: 'restrict',
      values: t.values.map((v) => ({ value: v.value, synonyms: (v.synonyms || []).filter(Boolean) })),
    })),
    intents: (data.intents || []).map((i) => {
      const slots = (i.slots || []).map((s) => ({
        name: s.name.replace(/\W/g, ''),
        type: pickType(s, typeNames),
        prompt: s.prompt,
        required: true,
      }));
      const names = new Set(slots.map((s) => s.name));
      return {
        name: i.name.replace(/\W/g, ''),
        description: i.description,
        // drop utterances that reference slots that don't exist
        utterances: (i.utterances || []).filter((u) => [...u.matchAll(/\{(\w+)\}/g)].every((m) => names.has(m[1]))),
        slots,
        confirmationPrompt: i.confirmationPrompt || '',
        declinationResponse: 'Okay, I won\'t do that. Anything else?',
        closingResponse: i.closingResponse || 'Done!',
        fulfillmentEnabled: false,
      };
    }),
  });
  return { bot, ms };
}
